return ['domain'=>'press-permit-core','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'bg-BG','project-id-version'=>'PublishPress Permissions Free 4.8.2','pot-creation-date'=>'2026-04-22T11:57:22+00:00','po-revision-date'=>'2026-05-26 19:59+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Permissions Free'=>'PublishPress Permissions Free','https://publishpress.com/presspermit'=>'https://publishpress.com/presspermit','PublishPress Permissions allows you to enable or deny access to posts, pages, categories, tags and more.'=>'PublishPress Permissions позволява да разрешите или откажете достъп до публикации, страници, категории, тагове и още.','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','Edit Tag for All Post Types'=>'Редактиране на етикет за всички типове публикации','Edit Tag for Posts'=>'Редактиране на етикет за публикации','Advanced Custom Fields'=>'Разширени персонализирани полета','Control front-end access to Field Groups with advanced permission management.'=>'Контрол на достъпа до групи полета с разширено управление на правата.','Control access to Field Groups'=>'Контрол на достъпа до групи полета','Front-end visibility restrictions'=>'Ограничения на видимостта на предния край','Integration with permission groups'=>'Интеграция с групи за разрешения','Beaver Builder'=>'Beaver Builder','Compatibility with Edit Permissions in Beaver Builder.'=>'Съвместимост с редактиране на разрешения в Beaver Builder.','Beaver editor integration'=>'Интеграция с редактора Beaver','Widget-level permission controls'=>'Контроли на разрешения на ниво виджет','Template access restrictions'=>'Ограничения на достъпа до шаблони','bbPress Forums'=>'bbPress форуми','Forum-specific permissions for bbPress with detailed control over forum access and participation.'=>'Права, специфични за форуми, за bbPress с детайлен контрол върху достъпа и участието във форума.','Forum-specific permissions'=>'Права, специфични за форуми','Topic creation restrictions'=>'Ограничения за създаване на теми','Forum access controls'=>'Контрол на достъпа до форума','BuddyPress'=>'BuddyPress','Assign post and term permissions to BuddyPress groups for enhanced content control.'=>'Присвояване на разрешения за публикации и термини на групи BuddyPress за подобрен контрол на съдържанието.','Assign post permissions to BuddyPress groups'=>'Присвояване на разрешения за публикации на групи BuddyPress','Assign term permissions to BuddyPress groups'=>'Присвояване на разрешения за термини на групи BuddyPress','Group-based content permissions'=>'Разрешения за съдържание на базата на групи','CMS Tree View'=>'Дървовиден изглед на CMS','Compatibility with Edit Permissions in CMS Tree View.'=>'Съвместимост с редактиране на разрешения в дървовидния изглед на CMS.','Permission-aware tree view'=>'Дървовиден изглед с осъзнаване на разрешенията','Hierarchical content controls'=>'Йерархични контроли на съдържанието','Elementor'=>'Elementor','Compatibility with Edit Permissions in Elementor.'=>'Съвместимост с редактиране на разрешения в Elementor.','Elementor editor integration'=>'Интеграция на редактора на Elementor','The Events Calendar'=>'Календар на събитията','Apply permission controls to events and event-related content.'=>'Прилагане на контроли за разрешения към събития и съдържание, свързано със събития.','Event post permissions'=>'Разрешения за публикации на събития','Event taxonomy controls'=>'Контроли на таксономията на събития','Nested Pages'=>'Наследени страници','Compatibility with Edit Permissions in Nested Pages.'=>'Съвместимост с редактиране на разрешения в наследените страници.','Permission-aware nested view'=>'Вложен изглед с осъзнаване на разрешения','Quick edit integration'=>'Интеграция за бързо редактиране','PublishPress Statuses'=>'Статуси на PublishPress','Compatibility with PublishPress Statuses plugin.'=>'Съвместимост с плъгина за статуси на PublishPress.','Custom status permissions'=>'Разрешения за персонализирани статуси','Workflow-specific access controls'=>'Контроли за достъп, специфични за работния процес','Status-based editing capabilities'=>'Възможности за редактиране на базата на статуса','Relevanssi'=>'Relevanssi','Filter search results based on View Permissions for secure content discovery.'=>'Филтрирайте резултатите от търсенето на базата на разрешенията за изглед за сигурно откриване на съдържание.','Search result filtering'=>'Филтриране на резултатите от търсенето','Permission-aware indexing'=>'Индексиране с осъзнаване на разрешения','Secure content discovery'=>'Сигурно откритие на съдържание','SearchWP'=>'SearchWP','Compatibility with SearchWP term filtering for advanced search capabilities.'=>'Съвместимост с филтрирането на термини в SearchWP за разширени възможности за търсене.','Permission-aware search results'=>'Резултати от търсенето с осъзнаване на разрешения','Term-based filtering'=>'Филтриране на базата на термини','Advanced search controls'=>'Разширени контроли за търсене','WooCommerce'=>'WooCommerce','Apply permission controls to WooCommerce products and product categories.'=>'Приложете контроли за разрешения към продуктите и категориите продукти на WooCommerce.','Product permissions'=>'Разрешения за продукти','Product category controls'=>'Контроли за категориите на продуктите','WPML'=>'WPML','Multilingual support with permission synchronization across content translations.'=>'Многоезична поддръжка с синхронизация на разрешенията между преводите на съдържанието.','Permission synchronization across translations'=>'Синхронизация на разрешенията между преводите','Language-specific content access'=>'Достъп до съдържание по езикови спецификации','Multilingual permission management'=>'Управление на разрешенията за многоезичност','Yoast SEO'=>'Yoast SEO','Exclude restricted posts from XML sitemaps to maintain proper SEO indexing.'=>'Изключете ограничените публикации от XML картите на сайта, за да поддържате правилна SEO индексация.','Sitemap filtering for restricted content'=>'Филтриране на картата на сайта за ограничено съдържание','Search engine visibility controls'=>'Контроли за видимост в търсачките','Permission-aware XML sitemaps'=>'XML карти на сайта с осведомяване за разрешенията','YooTheme'=>'YooTheme','Compatibility with YooTheme builder and term permissions.'=>'Съвместимост с конструктора на YooTheme и разрешенията на термините.','Builder interface compatibility'=>'Съвместимост на интерфейса на конструктора','Term permission integration'=>'Интеграция на разрешенията на термините','Template access controls'=>'Контроли за достъп до шаблони','Viewing'=>'Прегледане','Access Circles'=>'Кръгове за достъп','Editing Permissions'=>'Разрешения за редактиране','Compatibility Pack'=>'Пакет за съвместимост','Teaser'=>'Тийзър','File Access'=>'Достъп до файл','Membership'=>'Членство','User Posts'=>'Публикации на потребители','Visibility Circles and Editorial Circles block access to content not authored by other group members.'=>'Видимостта на кръговете и редакционните кръгове блокира достъпа до съдържание, което не е авторствано от други членове на групата.','Post-specific and category-specific permissions for creation and editing.'=>'Разрешения, специфични за публикации и категории, за създаване и редактиране.','Integration with ACF, bbPress, BuddyPress, Relevanssi, WPML and other plugins; enhanced Multisite support.'=>'Интеграция с ACF, bbPress, BuddyPress, Relevanssi, WPML и други плъгини; подобрена поддръжка на Multisite.','On the site front end, display teaser text for unreadable posts instead of hiding them.'=>'На предния край на сайта, показвайте текст на тийзър за нечетими публикации вместо да ги скривате.','Restrict direct file requests based on user\'s access to the page a file is attached to.'=>'Ограничаване на директни заявки за файлове въз основа на достъпа на потребителя до страницата, към която е прикрепен файл.','Time-limit access customizations by delaying or expiring Permission Group membership.'=>'Персонализиране на времевите ограничения за достъп чрез забавяне или изтичане на членството в групата за разрешения.','Auto-create a page for each user of specified roles. Compatible with several Team / Staff plugins.'=>'Автоматично създаване на страница за всеки потребител на определени роли. Съвместим с няколко плъгина за екип / персонал.','Visibility Circles and Editorial Circles block access to content not authored by other group members. Any WP Role, BuddyPress Group or custom Group can be marked as a Circle for specified post types.'=>'Видимостта на кръговете и редакционните кръгове блокира достъпа до съдържание, което не е авторствано от други членове на групата. Всяка роля на WP, група на BuddyPress или персонализирана група може да бъде маркирана като кръг за определени типове публикации.','Supports content-specific permissions for editing, term assignment and page parent selection. In combination with other modules, supports workflow statuses, PublishPress and PublishPress Revisions.'=>'Поддържа разрешения, специфични за съдържание, за редактиране, присвояване на термини и избор на родителска страница. В комбинация с други модули, поддържа статуси на работния процес, PublishPress и PublishPress Revisions.','Adds compatibility or integration with ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML, various other plugins. Configure any BuddyPress Group as a Permissions Group. For multisite, provides network-wide Permission Groups.'=>'Добавя съвместимост или интеграция с ACF, bbPress, Relevanssi, CMS Tree Page View, Custom Post Type UI, Subscribe2, WPML и различни други плъгини. Конфигурирайте всяка група на BuddyPress като група за разрешения. За Multisite предоставя мрежови групи за разрешения.','On the site front end, replace non-readable content with placeholder text. Can be enabled for any post type. Custom filters are provided but no programming is required for basic usage.'=>'На предния край на сайта, заменете нечетивното съдържание с текст за запълване. Може да бъде активирано за всеки тип публикация. Предоставени са персонализирани филтри, но не е необходимо програмиране за основна употреба.','Filters direct file access, based on user\'s access to post(s) which the file is attached to. No additional configuration required. Creates/modifies .htaccess file in uploads folder (and in main folder for multisite).'=>'Филтрира директния достъп до файлове, въз основа на достъпа на потребителя до публикации, към които е прикрепен файл. Не се изисква допълнителна конфигурация. Създава/модифицира файла .htaccess в папката с качвания (и в основната папка за multisite).','Allows Permission Group membership to be date-limited (delayed and/or scheduled for expiration). Simple date picker UI alongside group membership selection.'=>'Позволява членството в групата за разрешения да бъде ограничено във времето (забавено и/или планирано за изтичане). Прост интерфейс за избор на дата заедно с избора на членство в групата.','Create or synchronize posts to match users. Designed for Team / Staff plugins, but with broad usage potential.'=>'Създайте или синхронизирайте публикации, за да съответстват на потребителите. Проектиран за плъгини за екип / персонал, но с широк потенциал за употреба.','If you like %s, please leave us a %s rating. Thank you!'=>'Ако ви харесва %s, моля, оставете ни оценка %s. Благодаря ви!','About PublishPress Permissions'=>'За PublishPress Permissions','About'=>'За нас','Permissions Documentation'=>'Документация за разрешения','Documentation'=>'Документация','Contact the PublishPress team'=>'Свържете се с екипа на PublishPress','Contact'=>'Контакт','Permission Group'=>'Група разрешения','Specific Permissions: restrictions (\'Blocked\') take priority over additions (\'Enabled\')'=>'Специфични разрешения: ограничения (\'Блокирано\') имат предимство пред добавки (\'Активирано\')','Specific Permissions: no restrictions (\'Blocked\') can be applied to custom-defined groups'=>'Специфични разрешения: няма ограничения (\'Блокирано\') могат да се прилагат за потребителски дефинирани групи','Extra Roles assignment available for {All} and {Anonymous} metagroups'=>'Налична е присвояване на допълнителни роли за метагрупи {All} и {Anonymous}','Allow the {All} and {Anonymous} metagroups to be granted specific reading permissions for private content'=>'Позволете на метагрупите {All} и {Anonymous} да получат специфични разрешения за четене на частно съдържание','Users who have specific editing permissions for a post or attachment can also delete it'=>'Потребителите, които имат специфични разрешения за редактиране на публикация или прикачен файл, могат също да я изтрият','Users who have custom editing permissions for an attachment can also delete it'=>'Потребителите, които имат персонализирани разрешения за редактиране на прикачен файл, могат също да го изтрият','Disable front end filtering if logged user is a content administrator (normally filter to force inclusion of readable private posts in get_pages() listing, post counts, etc.'=>'Деактивирайте филтрирането на предния край, ако регистрираният потребител е администратор на съдържание (обикновено филтър, за да се принуди включването на четими частни публикации в списъка get_pages(), брой публикации и т.н.','Disable front end filtering for all users (subject to limitation by PP_UNFILTERED_FRONT_TYPES)'=>'Деактивирайте филтрирането на предния край за всички потребители (подлежи на ограничение от PP_UNFILTERED_FRONT_TYPES)','Comma-separated list of post types to limit the effect of PP_UNFILTERED_FRONT and apply_filters( \'presspermit_skip_cap_filtering\' )'=>'Списък с типове публикации, разделени с запетаи, за ограничаване на ефекта от PP_UNFILTERED_FRONT и apply_filters( \'presspermit_skip_cap_filtering\' )','Specific Permissions: additions (\'Enabled\') are not applied, cannot be assigned'=>'Специфични разрешения: добавките (\'Активирано\') не се прилагат, не могат да бъдат присвоени','Don\'t assign or apply specific permissions for the \'post\' type'=>'Не присвоявайте или прилагайте специфични разрешения за типа \'публикация\'','Don\'t assign or apply specific permissions for the \'page\' type'=>'Не присвоявайте или прилагайте специфични разрешения за типа \'страница\'','Don\'t assign or apply specific permissions for the \'media\' type'=>'Не присвоявайте или прилагайте специфични разрешения за типа \'медии\'','Don\'t assign or apply specific permissions for the specified custom post type'=>'Не присвоявайте или прилагайте специфични разрешения за определения потребителски тип публикация','Include scheduled posts in the posts query if user can edit them'=>'Включете планираните публикации в запитването за публикации, ако потребителят може да ги редактира','Don\'t filter term post counts in get_terms() call'=>'Не филтрирайте броя на термините в извикването на get_terms()','Leave unreadable posts on WP Navigation Menus'=>'Оставете нечетими публикации в менюта за навигация на WP','Don\'t apply CSS to hide empty Nav Menus'=>'Не прилагайте CSS, за да скриете празни навигационни менюта','For legacy Nav Menus, hide empty nav menu div'=>'За наследствени навигационни менюта, скрийте празния div на навигационното меню','Leave terms with no readable posts on WP Navigation Menus'=>'Оставете термините без четими публикации в менюта за навигация на WP','When Teaser is applied with Redirect enabled, append original url as redirect_to argument'=>'Когато Teaser е приложен с активиран Redirect, добавете оригиналния url като аргумент redirect_to','For Teaser compatibility, specify a redirect argument to use instead of redirect_to'=>'За съвместимост с Teaser, посочете аргумент за пренасочване, който да се използва вместо redirect_to','For Teaser compatibility, specify an additional redirect argument other than redirect_to'=>'За съвместимост с Teaser, посочете допълнителен аргумент за пренасочване, различен от redirect_to','For Teaser compatibility, prevent the pp_permissions argument from being appended to redirects'=>'За съвместимост с Teaser, предотвратете добавянето на аргумента pp_permissions към пренасочванията','Filter priority for \'get_pages\' filter (default: 1)'=>'Приоритет на филтъра за филтъра \'get_pages\' (по подразбиране: 1)','Don\'t include readable private pages in the Pages widget or other wp_list_pages() / get_pages() results    '=>'Не включвайте четими частни страници в джаджата Pages или в резултатите от wp_list_pages() / get_pages()    ','If some pages have been suppressed from get_pages() results, change child pages\' corresponding post_parent values to a visible ancestor'=>'Ако някои страници са потискани от резултатите на get_pages(), променете съответстващите стойности на post_parent на децата на видим предшественик','Never modify the post_parent value in the get_pages() result set, even if some pages have been suppressed'=>'Никога не променяйте стойността на post_parent в набора от резултати на get_pages(), дори ако някои страници са потискани','For performance, change the get_pages() database query to return only a subset of fields, excluding post_content'=>'За производителност, променете запитването в базата данни на get_pages() да връща само подмножество от полета, без post_content','Don\'t apply content teaser to get_pages() results (leave unreadable posts hidden)'=>'Не прилагайте съдържание Teaser на резултатите от get_pages() (оставете нечетимите публикации скрити)','If some terms have been suppressed from get_terms() results, change child terms\' corresponding parent values to a visible ancestor'=>'Ако някои термини са потискани от резултатите на get_terms(), променете съответстващите родителски стойности на децата на видим предшественик','Never modify the parent value in the get_terms() result set, even if some terms have been suppressed'=>'Никога не променяйте стойността на родителя в набора от резултати на get_terms(), дори ако някои термини са потискани','Set Author to current user if autoset_post_author / autoset_page_author capability is assigned'=>'Задайте автора на текущия потребител, ако е назначена способността autoset_post_author / autoset_page_author','Leave Media Library with normal access criteria based on user\'s role capabilities '=>'Оставете Медийната библиотека с нормални критерии за достъп, основани на възможностите на ролята на потребителя ','Accommodate front end uploading solutions that require page editing capabilities for the async upload request'=>'Приемайте решения за качване на фронтенд, които изискват възможности за редактиране на страници за асинхронното качване на заявки','Treat media attached to unregistered post types as unattached, to avoid improper and confusing filtering'=>'Третирайте медии, прикрепени към нерегистрирани типове публикации, като неприкрепени, за да избегнете неправилно и объркващо филтриране','Attached Files Private setting available'=>'Налична настройка за частни прикрепени файлове','Comma-separated list of mime types to exclude from File Access filtering'=>'Списък от mime типове, разделени с запетаи, за изключване от филтрирането на достъп до файлове','Comma-separated list of mime types to include in File Access filtering (bypassing others)'=>'Списък от mime типове, разделени с запетаи, за включване в филтрирането на достъп до файлове (пропускайки другите)','When file access is blocked, do not set the WP_Query 404 / 403 property'=>'Когато достъпът до файлове е блокиран, не задавайте свойството WP_Query 404 / 403','HTTP status code to send when file access is blocked'=>'HTTP статус код за изпращане, когато достъпът до файлове е блокиран','On Users listing, Permission groups in custom column are list filter links instead of group edit links'=>'В списъка с потребители, групите с разрешения в персонализираната колона са връзки за филтриране на списъка вместо връзки за редактиране на групи','Unlock Permissions > Settings > Core > Admin Back End > \'Hide non-editable posts\''=>'Отключете Разрешения > Настройки > Основни > Администраторски Фронтенд > \'Скрийте непредEditable публикации\'','Within the async-upload.php script, filter author\'s retrieval of the attachment they just uploaded'=>'В рамките на скрипта async-upload.php, филтрирайте възстановяването на автора за прикачения файл, който току-що е качил','Don\'t filter comment display or moderation within wp-admin'=>'Не филтрирайте показването на коментари или модерацията в wp-admin','Allow Administrators to be added to Permission Groups, even though they are not restricted'=>'Позволете на администраторите да бъдат добавяни в групи с разрешения, въпреки че не са ограничени','If propagating permissions are assigned to a page branch, overwrite any explicitly assigned permissions in sub-pages'=>'Ако разрешенията за разпространение са зададени на клон на страница, заменете всякакви изрично зададени разрешения в подстраниците','Max number of specific permissions to insert in a single database query (default 1000)'=>'Максимален брой специфични разрешения за вмъкване в една заявка към базата данни (по подразбиране 1000)','Don\'t tweak the admin menu indexes to position Permissions menu under Users'=>'Не променяйте индексите на администраторското меню, за да позиционирате менюто за разрешения под Потребители','Don\'t add a Permissions menu. Instead, add menu items to the Users and Settings menus.'=>'Не добавяйте меню за разрешения. Вместо това добавете елементи от менюто в менюто Потребители и Настройки.','Customize Permissions screen title for Groups'=>'Персонализирайте заглавието на екрана за разрешения за Групи','Customize Permission Groups caption on user profile'=>'Персонализирайте надписа на групите с разрешения в профила на потребителя','Only one group is selectable on Add User screen'=>'Само една група е избираема на екрана Добавяне на потребител','Only one group is selectable on Edit User screen'=>'Само една група е избираема на екрана Редактиране на потребител','Display a custom hint on Permissions > User Groups'=>'Показване на персонализиран提示 за Разрешения > Потребителски групи','Max number of non-hierarchical posts / terms to display at one time (per page)'=>'Максимален брой непарентни публикации / термини, които да се показват едновременно (на страница)','Max number of hierarchical posts / terms to display at one time (per page)'=>'Максимален брой парентни публикации / термини, които да се показват едновременно (на страница)','Disable auto-determination of how many levels of page tree to make visble by default. Instead, use specified value.'=>'Деактивиране на автоматичното определяне на това колко нива на дървото на страниците да бъдат видими по подразбиране. Вместо това, използвайте зададена стойност.','Target number of visible pages/terms, used for auto-determination of number of visible levels'=>'Целеви брой видими страници/термини, използвани за автоматично определяне на броя на видимите нива','Make search function on the post selection metabox look at post content'=>'Нека функцията за търсене в метабокса за избор на публикации да се отнася към съдържанието на публикацията','Make search function on the post selection metabox look at post excerpt'=>'Нека функцията за търсене в метабокса за избор на публикации да се отнася към откъса на публикацията','Search by last name instead of display name'=>'Търсене по фамилно име вместо по показано име','User field to search by default'=>'Потребителско поле за търсене по подразбиране','User meta fields selectable for search (comma-separated)'=>'Избираеми мета полета на потребителя за търсене (разделени с запетаи)','User meta fields which should be treated as numeric (comma-separated)'=>'Мета полета на потребителя, които трябва да се третират като числови (разделени с запетаи)','User meta fields which should be treated as boolean (comma-separated)'=>'Мета полета на потребителя, които трябва да се третират като булеви (разделени с запетаи)','Use display name for search results instead of user_login'=>'Използвайте показаното име за резултатите от търсенето вместо user_login','When synchronizing role metagroups to currently defined WP roles, don\'t delete groups for previously defined WP roles.'=>'При синхронизиране на метагрупи на роли с в момента дефинирани роли в WP, не изтривайте групи за преди определени роли в WP.','Force detection of WP user roles which are appended dynamically but not stored to the WP database.'=>'Принудително откриване на роли на потребители в WP, които се добавят динамично, но не се съхраняват в базата данни на WP.','To save memory on front end access, don\'t register any filters related to content editing'=>'За да спестите памет при достъп от фронтенд, не регистрирайте никакви филтри, свързани с редактиране на съдържанието','Attached media do not have any comments, so don\'t append clauses to comment queries for them'=>'Прикачените медии нямат коментари, така че не добавяйте клаузи към заявките за коментари за тях','Reduce overhead of pages query (in get_pages() and wp-admin) by defaulting fields to a set list that does not include post_content '=>'Намалете разходите за запитване на страници (в get_pages() и wp-admin) чрез задаване на полета на предварително определен списък, който не включва post_content ','Reduce overhead of wp-admin posts query by defaulting fields to a set list that does not include post_content '=>'Намалете разходите за запитване на публикации в wp-admin, като зададете полета на предварително определен списък, който не включва post_content ','Reduce overhead of wp-admin Media query by defaulting fields to a set list that does not include post_content '=>'Намалете разходите за запитване на медии в wp-admin, като зададете полета на предварително определен списък, който не включва post_content ','Reduce overhead of wp-admin query for specified custom post type by defaulting fields to a set list that does not include post_content '=>'Намалете натоварването на wp-admin заявката за указан тип персонализирана публикация, като по подразбиране полетата са зададени на списък, който не включва post_content','Work around database setup warnings (at plugin activation) on some servers'=>'Работете около предупреждения за настройка на базата данни (при активиране на плъгин) на някои сървъри','Development use only (suppresses post_status = \'publish\' clause for unfiltered post types with anonymous user)'=>'Само за разработка (потиска клаузата post_status = \'publish\' за непремахнати типове публикации с анонимен потребител)','Development use only (on front end, do not replace \'post_status = \'publish\'\' clause with filtered equivalent)'=>'Само за разработка (на предния край не заменяйте клаузата \'post_status = \'publish\'\' с филтриран еквивалент)','Logged In'=>'Влезли','Not Logged In'=>'Не влезли','Everyone'=>'Всеки','Change Request Notifications'=>'Уведомления за заявки за промяна','Submitted Revision Editors'=>'Представена ревизия','Scheduled Change Notifications'=>'Планирани уведомления за промяна','Scheduled Revision Monitors'=>'Планирани наблюдатели на ревизии','Authenticated site users, except for Administrators'=>'Аутентицирани потребители на сайта, с изключение на администраторите','Anonymous users (not logged in)'=>'Анонимни потребители (не влезли)','All users (including anonymous)'=>'Всички потребители (включително анонимни)','All users with the WordPress role of %s'=>'Всички потребители с роля WordPress %s','%1$s %2$s'=>'%1$s %2$s','%1$s won&#39;t work until you upgrade PHP to version %2$s or later. Current version: %3$s'=>'%1$s няма да работи, докато не актуализирате PHP до версия %2$s или по-нова. Текуща версия: %3$s','%1$s won&#39;t work until you upgrade %2$s to version %3$s or later.'=>'%1$s няма да работи, докато не актуализирате %2$s до версия %3$s или по-нова.','%1$s won&#39;t work until you upgrade WordPress to version %2$s or later.'=>'%1$s няма да работи, докато не актуализирате WordPress до версия %2$s или по-нова.','This version of %1$s cannot work with your current %2$s version. Please upgrade it to %3$s or later.'=>'Тази версия на %1$s не може да работи с текущата версия на %2$s. Моля, актуализирайте я до %3$s или по-нова.','Duplicate %1$s module activated (%2$s in folder %3$s).'=>'Активиран дублиран модул %1$s (%2$s в папка %3$s).','Dismiss'=>'Отхвърли','Custom Group'=>'Персонализирана група','Custom Groups'=>'Персонализирани групи','Groups'=>'Групи','(using default capabilities due to invalid %s definition)'=>'(използване на стандартни възможности поради невалидно %s определение)','%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s'=>'%1$s&nbsp;%2$s&nbsp;%3$s-&nbsp;%4$s%5$s%6$s','%1$s&nbsp;%2$s%3$s'=>'%1$s&nbsp;%2$s%3$s','Your license key has expired. For updates to PublishPress Permissions Pro and priority support, %splease renew%s.'=>'Вашият лицензионен ключ е изтекъл. За актуализации на PublishPress Permissions Pro и приоритетна поддръжка, %sмоля, подновете%s.','[WP %s]'=>'[WP %s]','All users with a WordPress %s role'=>'Всички потребители с роля WordPress %s','All users who are logged in and have a role on the site'=>'Всички потребители, които са влезли и имат роля на сайта','Users to notify when revisions are submitted'=>'Потребители за уведомяване, когато са представени ревизии','Users to notify when scheduled revisions are published'=>'Потребители за уведомяване, когато са публикувани планирани ревизии','(login timed out)'=>'(времето за вход изтече)','View'=>'Преглед','Control assignment of selected terms to %s.'=>'Контролирайте присвояването на избраните термини на %s.','Control if this %s can be selected as a Parent Page.'=>'Контролирайте дали този %s може да бъде избран като родителска страница.','Control editing of selected %s.'=>'Контрол на редактирането на избрания %s.','Control publishing of selected %s.'=>'Контрол на публикуването на избрания %s.','Control deletion of selected %s.'=>'Контрол на изтриването на избрания %s.','Control term management for selected %s.'=>'Контрол на управлението на термини за избрания %s.','Control frontend viewing of selected %s.'=>'Контрол на предния изглед на избрания %s.','Control who can create a revision of this %s.'=>'Контролирайте кой може да създаде ревизия на този %s.','Control who can submit a revision of this %s.'=>'Контролирайте кой може да подаде ревизия на този %s.','Control which terms can be set as a Parent of other terms.'=>'Контролирайте кои термини могат да бъдат зададени като родител на други термини.','Allow users to manage selected terms.'=>'Позволете на потребителите да управляват избраните термини.','Control management of selected groups.'=>'Контрол на управлението на избраните групи.','Enable'=>'Активиране','Block'=>'Блокиране','Limit to'=>'Ограничаване до','Expand access to allow specified items regardless of role capabilities or restrictions.'=>'Разширете достъпа, за да позволите определени елементи, независимо от възможностите или ограниченията на ролята.','Restrict access by blocking specified items unless an "Enabled" exception is also stored.'=>'Ограничете достъпа, като блокирате определени елементи, освен ако също не е съхранена изключение с "Активирано".','Restrict access by limiting role capabilities to apply only for specified items. Users still need capabilities in their main role or extra roles.'=>'Ограничете достъпа, като ограничите възможностите на ролята да важат само за определени елементи. Потребителите все още трябва да имат възможности в основната си роля или допълнителни роли.','Using group membership to block access is not recommended. Consider reducing the user\'s role capabilities and using group membership to add access.'=>'Не се препоръчва използването на членство в група за блокиране на достъп. Обмислете намаляване на възможностите на ролята на потребителя и използване на членство в група, за да добавите достъп.','Selected:'=>'Избрано:','Nav Menus (Legacy)'=>'Навигационни менюта (Наследство)','Legacy'=>'Наследство','%s:'=>'%s:','Selected %s:'=>'Избрано %s:','Sub-%s:'=>'Под-%s:','All Statuses'=>'Всички статуси','%s Visibility'=>'%s Видимост','No user/group specified.'=>'Не е посочен потребител/група.','You are not permitted to do that.'=>'Нямате разрешение да направите това.','Invalid user ID.'=>'Невалиден потребителски ID.','Invalid group ID.'=>'Невалиден групов ID.','Roles updated.'=>'Ролите са актуализирани.','Specific Permissions updated.'=>'Специфичните разрешения са актуализирани.','Roles and Permissions copied.'=>'Ролите и разрешенията са копирани.','Group updated.'=>'Групата е обновена.','Back to permissions list'=>'Назад към списъка с разрешения','Edit User Permissions'=>'Редактиране на разрешенията на потребителя','Add User Permissions'=>'Добавяне на разрешения за потребителя','Edit Permissions'=>'Редактиране на разрешенията','Edit Permissions (%s)'=>'Редактиране на разрешения (%s)','%sEdit WordPress Role%s'=>'%sРедактиране на ролята на WordPress%s','Edit role capabilities directly'=>'Редактиране на способностите на ролята директно','Add New'=>'Добави нов','Name:'=>'Име:','Email:'=>'Имейл:','Primary Role:'=>'Основна роля:','User ID:'=>'ID на потребителя:','Member since:'=>'Член от:','Description:'=>'Описание:','Update Permissions'=>'Актуализиране на разрешенията','View Full Profile'=>'Преглед на пълния профил','Extra Roles %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Допълнителни Роли %1$s(от основната роля или %2$sgroup membership%3$s)%4$s','Specific Permissions %1$s(from primary role or %2$sgroup membership%3$s)%4$s'=>'Специфични Права %1$s(от основната роля или %2$sgroup membership%3$s)%4$s','View currently stored user permissions:'=>'Преглед на текущо съхранените разрешения на потребителя:','%1$sUsers who have Extra Roles assigned directly%2$s'=>'%1$sПотребители, които имат допълнителни роли, зададени директно%2$s','%1$sUsers who have Specific Permissions assigned directly%2$s'=>'%1$sПотребители, които имат специфични разрешения, зададени директно%2$s','%1$sUsers who have Extra Roles or Specific Permissions directly%2$s'=>'%1$sПотребители, които имат допълнителни роли или специфични 